//plot x,y,z to point on circle
smp=sample*6.283;
xp=y*cos(smp )*0.05;
yp=cos(smp )*0.05;
zp=0;


//alter shape;
angy=y*cos(sample*6.28*4 +t1 )*6.28;
xq=xp*cos(angy) - zp*y*cos(angy);
zq=xp*y*cos(angy) + zp*cos(angy);
xp=xq;
zp=zq;


//rotate on y axis;
angy=t1*0.1;
xq=xp*cos(angy) - zp*y*cos(angy);
zq=xp*y*cos(angy) + zp*cos(angy);
xp=xq;
zp=zq;

//rotate on x axis
axs1 = y*cos(t1*0.15) + 1.6;
yq= yp*cos(axs1) - zp*y*cos(axs1);
zq= yp*y*cos(axs1) + zp*cos(axs1);
yp=yq;
zp=zq;

//rotate on y axis again
axs2 = y*cos(t1*0.1)*3.3;
xq=xp*cos(axs2) - zp*y*cos(axs2);
zq=xp*y*cos(axs2) + zp*cos(axs2);
xp=xq;
zp=zq;

//stretch y axis to compensate for aspect ratio
yp=yp*1.2;

//push forward into viewpace
zp=zp+2.1;

//project x,y,z into screenspace
xs=xp/zp;
ys=yp/zp;

//center 0,0 in middle of screen
x=xs+0.5+q4;
y=ys+0.5+q5;

